def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(src, dst):
        sx, sy = src
        dx, dy = dst
        return [clamp_step(dx - sx), clamp_step(dy - sy)]

    def dist1(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], int) and isinstance(v[1], int):
            return [v[0], v[1]]
        return None

    def best_target(src, items):
        best = None
        best_d = None
        for item in items or []:
            p = first_pos(item)
            if p is None:
                continue
            d = dist1(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = first_pos(observation.get("self_position")) or [0, 0]
    opp_pos = first_pos(observation.get("opponent_position")) or self_pos
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        target = max(corners, key=lambda c: dist1(c, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        target = best_target(self_pos, targets)
        if target is None:
            target = opp_pos
        return step_toward(self_pos, target)

    resources = observation.get("resources")
    target = best_target(self_pos, resources)
    if target is not None:
        return step_toward(self_pos, target)

    enemy = opp_pos
    if enemy != self_pos:
        return step_toward(self_pos, enemy)

    return [0, 0]

